const body = $input.first().json.body || $input.first().json;
const message = String(body.message || '').toLowerCase();
const expenses = Array.isArray(body.expenses) ? body.expenses : [];
const money = (value) => Number(value || 0).toFixed(2);
const sum = (list) => list.reduce((total, item) => total + Number(item.amount || 0), 0);

if (!expenses.length) {
  return [{ json: { reply: 'There are no expenses available, so I cannot calculate spending.' } }];
}

const categories = ['Food', 'Transport', 'Shopping', 'Bills', 'Entertainment', 'Other'];
const matchedCategory = categories.find((category) => message.includes(category.toLowerCase()));

let reply = '';
if (message.includes('largest') || message.includes('biggest')) {
  const largest = [...expenses].sort((a, b) => Number(b.amount) - Number(a.amount))[0];
  reply = `The largest expense is ${money(largest.amount)} on ${largest.date} (${largest.category}).`;
} else if (matchedCategory) {
  const filtered = expenses.filter((item) => item.category === matchedCategory);
  reply = filtered.length
    ? `${matchedCategory} spending is ${money(sum(filtered))} across ${filtered.length} expense(s).`
    : `There are no ${matchedCategory} expenses in the current data.`;
} else if (message.includes('by category') || message.includes('breakdown')) {
  reply = 'Spending by category:\n' + categories
    .map((category) => {
      const filtered = expenses.filter((item) => item.category === category);
      return filtered.length ? `${category}: ${money(sum(filtered))}` : null;
    })
    .filter(Boolean)
    .join('\n');
} else if (message.includes('recent') || message.includes('latest')) {
  const recent = [...expenses].sort((a, b) => String(b.date).localeCompare(String(a.date))).slice(0, 5)
    .map((item) => `${item.date}: ${money(item.amount)} (${item.category})`);
  reply = `Your most recent expenses:\n${recent.join('\n')}`;
} else if (message.includes('total') || message.includes('how much') || message.includes('spend')) {
  reply = `Your total spending is ${money(sum(expenses))} across ${expenses.length} expense(s).`;
} else {
  reply = 'I can answer totals, category spending, the largest expense, and recent spending from the expenses sent with the request. I will not invent values.';
}

return [{ json: { reply } }];
